#!/usr/bin/env python3

"""
Check exception chaining after our changes
"""

from dataclasses import dataclass
try:
    from typing import Annotated, TypeAlias
except ImportError:
    from typing_extensions import Annotated, TypeAlias
from mashumaro import DataClassDictMixin

PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]

def deserialize_with_custom_exception(value):
    print(f"Custom deserializer called with: {value}")
    if value < 0:
        # Throw a custom exception that should be preserved as cause
        raise RuntimeError("Custom validation failed!")
    return value

@dataclass
class MyClass(DataClassDictMixin):
    value: PositiveInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_with_custom_exception,
            }
        }

def main():
    print("=== Testing exception chaining ===")

    # Test invalid case - should have our custom exception as cause
    try:
        obj = MyClass.from_dict({"value": -5})
        print(f"Invalid case unexpectedly succeeded: {obj}")
    except Exception as e:
        print(f"Main exception: {type(e).__name__}: {e}")
        print(f"Exception cause: {e.__cause__}")
        if e.__cause__:
            print(f"Cause type: {type(e.__cause__).__name__}")
            print(f"Cause message: {e.__cause__}")
            if isinstance(e.__cause__, RuntimeError) and "Custom validation failed!" in str(e.__cause__):
                print("✓ Custom exception preserved as cause")
            else:
                print("? Cause is different than expected")
        else:
            print("✗ No cause preserved")

if __name__ == "__main__":
    main()
